-- Product 16: complete exercise media and alternatives schema.
alter table public.exercises add column if not exists aliases jsonb not null default '[]'::jsonb,add column if not exists joint_actions text[] not null default '{}',add column if not exists laterality text not null default 'bilateral',add column if not exists exercise_type text not null default 'strength',add column if not exists settings text[] not null default '{}',add column if not exists production_ready boolean not null default false;
create table if not exists public.exercise_media(exercise_id uuid primary key references public.exercises(id) on delete cascade,video_path text not null unique,poster_path text not null unique,motion_spec jsonb not null,motion_spec_version text not null,render_version text not null,duration_seconds numeric(4,1) not null check(duration_seconds>0),codec text not null,dimensions text not null,provenance text not null,review_status text not null check(review_status in('pending','approved','rejected')),reviewed_at timestamptz,created_at timestamptz not null default now());
alter table public.exercise_media enable row level security;grant select on public.exercise_media to anon,authenticated;drop policy if exists "public reads approved exercise media" on public.exercise_media;create policy "public reads approved exercise media" on public.exercise_media for select to anon,authenticated using(review_status='approved');
create table if not exists public.exercise_alternatives(exercise_id uuid not null references public.exercises(id) on delete cascade,alternative_id uuid not null references public.exercises(id) on delete cascade,rank smallint not null check(rank between 1 and 6),shared_primary_muscles text[] not null check(cardinality(shared_primary_muscles)>0),review_status text not null default 'reviewed' check(review_status in('pending','reviewed','rejected')),primary key(exercise_id,alternative_id),unique(exercise_id,rank),check(exercise_id<>alternative_id));
alter table public.exercise_alternatives enable row level security;grant select on public.exercise_alternatives to anon,authenticated;drop policy if exists "public reads reviewed alternatives" on public.exercise_alternatives;create policy "public reads reviewed alternatives" on public.exercise_alternatives for select to anon,authenticated using(review_status='reviewed');delete from public.exercise_alternatives;